select ac_cargar_fuente($ac${"slug":"ley-bosques-26331","titulo":"Ley 26.331 de Presupuestos Mínimos de Protección Ambiental de los Bosques Nativos","organizacion":"Congreso de la Nación Argentina","url":"https://www.derecho.uba.ar/academica/derecho-abierto/archivos/Ley-26331.pdf","publicado":"2007","licencia":"Norma pública","contenido":"La ley obliga a cada provincia a realizar un Ordenamiento Territorial de Bosques Nativos con tres categorías: categoría I (rojo), sectores de muy alto valor de conservación que no deben transformarse; categoría II (amarillo), de valor medio, con uso sostenible; categoría III (verde), sectores que pueden transformarse. Crea el Fondo Nacional para el Enriquecimiento y la Conservación de los Bosques Nativos."}$ac$::jsonb);
select ac_cargar_fuente($ac${"slug":"reserva-costanera-sur","titulo":"Reserva Ecológica Costanera Sur","organizacion":"Gobierno de la Ciudad de Buenos Aires","url":"https://buenosaires.gob.ar/gcaba_historico/vicejefatura/ambiente/reservasecologicas/reserva-ecologica-costanera-sur","publicado":"2024","licencia":"Documento público","contenido":"La Reserva Ecológica Costanera Sur ocupa unas 350 hectáreas sobre un relleno hecho con escombros de demoliciones en los años setenta. Los ecosistemas se regeneraron espontáneamente durante décadas de abandono; está protegida desde 1986 y es sitio Ramsar desde 2005. Registra 343 especies de aves, alrededor de un tercio de la avifauna argentina, además de 10 mamíferos y 23 reptiles, incluido el lagarto overo."}$ac$::jsonb);
