select ac_cargar_fuente($ac${"slug":"icct-ev","titulo":"Life-cycle greenhouse gas emissions of passenger cars","organizacion":"ICCT — International Council on Clean Transportation","url":"https://theicct.org/wp-content/uploads/2025/07/ID-392-%E2%80%93-Life-cycle-GHG_report_final.pdf","publicado":"2025","licencia":"Uso con atribución","contenido":"Los autos eléctricos no tienen emisiones por el caño de escape, pero sí emisiones de ciclo de vida por la fabricación de la batería y por la electricidad de la red. Considerando todo el ciclo de vida emiten sustancialmente menos que un auto de combustión comparable en prácticamente todas las redes eléctricas estudiadas."}$ac$::jsonb);
